source='''from itertools import permutations

def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v}
    frames = []
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        perimeter = all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0,c1+1))
        perimeter = perimeter and all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0,r1+1))
        if perimeter:
            frames.append((color, r0, r1, c0, c1))
    frames.sort(key=lambda x: (x[1], x[3]))
    frame_colors = {f[0] for f in frames}
    marker_colors = sorted(colors - frame_colors)
    if len(marker_colors) != len(frames):
        raise ValueError("expected one marker color per outlined rectangle")
    needs = []
    for _, r0, r1, c0, c1 in frames:
        n = (r1-r0-1)*(c1-c0-1)
        needs.append((n+1)//2)  # top-left checkerboard phase
    counts = {color: sum(v == color for row in grid for v in row) for color in marker_colors}
    # Pair each rectangle with the scattered color whose count best matches its checker pattern.
    best = min(permutations(marker_colors), key=lambda perm: sum(abs(counts[col]-need) for col, need in zip(perm, needs)))
    out = [[0]*w for _ in range(h)]
    for color, r0, r1, c0, c1 in frames:
        for c in range(c0,c1+1):
            out[r0][c] = out[r1][c] = color
        for r in range(r0,r1+1):
            out[r][c0] = out[r][c1] = color
    for frame, marker in zip(frames, best):
        _, r0, r1, c0, c1 = frame
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                if (r-r0-1 + c-c0-1) % 2 == 0:
                    out[r][c] = marker
    return out
